/* ============================================================
   Global Aid Alliance — Stylesheet
   OKLCH color palette, mobile-first, accessible
   ============================================================ */

/* --- DESIGN TOKENS --- */
:root {
  /* Brand Colors (OKLCH) */
  --red-700:   oklch(35% 0.18 22);   /* deep crimson — headers, active states */
  --red-600:   oklch(42% 0.20 22);   /* primary brand red */
  --red-500:   oklch(50% 0.22 22);   /* #C41E3A equivalent */
  --red-400:   oklch(60% 0.18 22);   /* hover red */
  --red-100:   oklch(95% 0.04 22);   /* light red tint */
  --navy-800:  oklch(22% 0.06 240);  /* deepest navy */
  --navy-700:  oklch(28% 0.08 240);  /* #1B3A5C equivalent */
  --navy-600:  oklch(35% 0.09 240);
  --navy-100:  oklch(95% 0.02 240);
  --gray-900:  oklch(15% 0.01 240);
  --gray-700:  oklch(35% 0.01 240);
  --gray-500:  oklch(55% 0.01 240);
  --gray-300:  oklch(78% 0.01 240);
  --gray-100:  oklch(96% 0.005 240);
  --white:     oklch(100% 0 0);
  --warm-50:   oklch(98% 0.005 70);

  /* Typography */
  --font-head: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing scale */
  --sp-1: 0.25rem;
  --sp-2: 0.5rem;
  --sp-3: 0.75rem;
  --sp-4: 1rem;
  --sp-6: 1.5rem;
  --sp-8: 2rem;
  --sp-10: 2.5rem;
  --sp-12: 3rem;
  --sp-16: 4rem;
  --sp-20: 5rem;
  --sp-24: 6rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.10), 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 6px oklch(0% 0 0 / 0.07), 0 2px 4px oklch(0% 0 0 / 0.06);
  --shadow-lg: 0 10px 15px oklch(0% 0 0 / 0.10), 0 4px 6px oklch(0% 0 0 / 0.05);
  --shadow-xl: 0 20px 25px oklch(0% 0 0 / 0.12), 0 8px 10px oklch(0% 0 0 / 0.06);

  /* Transitions */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 220ms;
}

/* --- RESET & BASE --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* --- CONTAINER --- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

/* --- BUTTONS --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-2);
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1;
  border-radius: var(--radius-md);
  padding: 0.75rem 1.5rem;
  transition: background var(--duration) var(--ease),
              color var(--duration) var(--ease),
              transform 120ms var(--ease),
              box-shadow var(--duration) var(--ease);
  white-space: nowrap;
}

.btn-donate {
  background: var(--red-500);
  color: var(--white);
  border-radius: var(--radius-full);
  padding: 0.55rem 1.25rem;
  font-size: 0.875rem;
}
.btn-donate:hover { background: var(--red-400); box-shadow: var(--shadow-md); }

.btn-hero-primary {
  background: var(--red-500);
  color: var(--white);
  padding: 0.875rem 2rem;
  font-size: 1rem;
  box-shadow: var(--shadow-md);
}
.btn-hero-primary:hover { background: var(--red-400); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn-hero-primary:active { transform: translateY(0); }

.btn-hero-secondary {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.75);
  padding: 0.875rem 2rem;
  font-size: 1rem;
}
.btn-hero-secondary:hover { background: rgba(255,255,255,0.12); border-color: var(--white); }

.btn-outline {
  background: transparent;
  color: var(--red-500);
  border: 2px solid var(--red-500);
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
}
.btn-outline:hover { background: var(--red-500); color: var(--white); }

/* --- SECTION LABELS & HEADERS --- */
.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--red-500);
  margin-bottom: var(--sp-3);
}
.section-label.light { color: var(--red-100); }

.section-header {
  text-align: center;
  margin-bottom: var(--sp-12);
}
.section-header h2 { margin-bottom: var(--sp-4); }
.section-header p { color: var(--gray-500); max-width: 560px; margin: 0 auto; }

h1 { font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.15; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 700; line-height: 1.25; letter-spacing: -0.01em; }
h3 { font-size: 1.125rem; font-weight: 700; line-height: 1.35; }
h4 { font-size: 0.875rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; }

/* ============================================================
   HEADER
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  box-shadow: 0 1px 0 var(--gray-100);
}

.header-utility {
  background: var(--navy-700);
  color: var(--gray-300);
  font-size: 0.8rem;
  padding: 0.4rem 0;
  text-align: right;
}
.header-utility a { color: var(--gray-300); transition: color var(--duration); }
.header-utility a:hover { color: var(--white); }

.header-main { padding: var(--sp-3) 0; }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-6);
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  flex-shrink: 0;
}
.logo-text { display: flex; flex-direction: column; line-height: 1.2; }
.logo-name { font-size: 1rem; font-weight: 800; color: var(--navy-700); letter-spacing: -0.01em; }
.logo-tagline { font-size: 0.7rem; color: var(--gray-500); letter-spacing: 0.06em; text-transform: uppercase; }

/* Main nav */
.main-nav ul {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
}
.main-nav a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-700);
  padding: 0.4rem 0.65rem;
  border-radius: var(--radius-sm);
  transition: color var(--duration), background var(--duration);
}
.main-nav a:hover { color: var(--navy-700); background: var(--gray-100); }
.main-nav .nav-donate { color: var(--white) !important; margin-left: var(--sp-2); }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--sp-2);
  border-radius: var(--radius-sm);
}
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: transform var(--duration) var(--ease), opacity var(--duration);
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav */
.mobile-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: oklch(0% 0 0 / 0.4);
  z-index: 98;
}
.mobile-overlay.visible { display: block; }

@media (max-width: 900px) {
  .hamburger { display: flex; }
  .main-nav {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: min(320px, 85vw);
    background: var(--white);
    z-index: 99;
    padding: var(--sp-20) var(--sp-6) var(--sp-8);
    transform: translateX(100%);
    transition: transform 300ms var(--ease);
    box-shadow: var(--shadow-xl);
  }
  .main-nav.open { transform: translateX(0); }
  .main-nav ul { flex-direction: column; align-items: stretch; gap: var(--sp-1); }
  .main-nav a { display: block; padding: 0.75rem 1rem; font-size: 1rem; border-radius: var(--radius-md); }
  .main-nav .nav-donate { margin-left: 0; margin-top: var(--sp-4); text-align: center; }
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: 580px;
  display: flex;
  align-items: center;
  padding: var(--sp-20) 0;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    oklch(22% 0.06 240 / 0.92) 0%,
    oklch(22% 0.06 240 / 0.75) 50%,
    oklch(22% 0.06 240 / 0.30) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  background: var(--red-500);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--sp-6);
}
.hero-badge::before {
  content: '';
  width: 7px; height: 7px;
  background: var(--white);
  border-radius: 50%;
  animation: pulse 1.8s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.5; transform: scale(1.4); }
}

.hero h1 { color: var(--white); margin-bottom: var(--sp-6); }
.hero-sub { color: oklch(95% 0.01 240); font-size: 1.0625rem; line-height: 1.65; margin-bottom: var(--sp-8); max-width: 540px; }

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-4);
  align-items: center;
}

/* ============================================================
   MISSION
   ============================================================ */
.mission {
  background: var(--warm-50);
  padding: var(--sp-20) 0;
}
.mission-inner { max-width: 800px; margin: 0 auto; text-align: center; }
.mission-inner h2 { color: var(--navy-700); margin-bottom: var(--sp-6); }
.mission-lead { font-size: 1.125rem; color: var(--gray-700); margin-bottom: var(--sp-6); font-style: italic; }
.mission-body { color: var(--gray-500); line-height: 1.75; margin-bottom: var(--sp-10); }

.mission-principles {
  display: flex;
  justify-content: center;
  gap: var(--sp-8);
  flex-wrap: wrap;
}
.principle {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sp-2);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--navy-700);
}
.principle-icon { font-size: 1.75rem; }

/* ============================================================
   IMPACT STATS
   ============================================================ */
.impact-stats {
  background: var(--navy-700);
  padding: var(--sp-20) 0;
  color: var(--white);
}
.stats-intro { text-align: center; margin-bottom: var(--sp-12); }
.stats-intro h2 { color: var(--white); margin-bottom: var(--sp-4); }
.stats-intro p { color: oklch(80% 0.03 240); max-width: 560px; margin: 0 auto; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-6);
}
@media (min-width: 640px) { .stats-grid { grid-template-columns: repeat(4, 1fr); } }

.stat-card {
  text-align: center;
  background: oklch(100% 0 0 / 0.06);
  border: 1px solid oklch(100% 0 0 / 0.1);
  border-radius: var(--radius-xl);
  padding: var(--sp-8) var(--sp-4);
  transition: background var(--duration);
}
.stat-card:hover { background: oklch(100% 0 0 / 0.10); }

.stat-number {
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1;
  margin-bottom: var(--sp-3);
  letter-spacing: -0.02em;
  min-height: 1.1em;
}
.stat-label {
  font-size: 0.8125rem;
  color: oklch(75% 0.04 240);
  line-height: 1.4;
}

/* ============================================================
   PROGRAMS ACCORDION
   ============================================================ */
.programs {
  padding: var(--sp-20) 0;
  background: var(--white);
}

.accordion { display: flex; flex-direction: column; gap: 0; border-radius: var(--radius-lg); overflow: hidden; border: 1px solid var(--gray-100); box-shadow: var(--shadow-sm); }

.accordion-item { border-bottom: 1px solid var(--gray-100); }
.accordion-item:last-child { border-bottom: none; }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: var(--sp-4);
  padding: var(--sp-5) var(--sp-6);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy-700);
  text-align: left;
  background: var(--white);
  transition: background var(--duration), color var(--duration);
}
.accordion-trigger:hover { background: var(--gray-100); }
.accordion-trigger[aria-expanded="true"] { background: var(--red-100); color: var(--red-600); }
.accordion-trigger[aria-expanded="true"] .acc-icon { color: var(--red-500); }

.accordion-icon-wrap {
  flex-shrink: 0;
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex; align-items: center; justify-content: center;
  color: var(--navy-600);
  transition: background var(--duration), color var(--duration);
}
.accordion-trigger[aria-expanded="true"] .accordion-icon-wrap { background: var(--red-500); color: var(--white); }

.accordion-trigger span { flex: 1; }

.chevron {
  flex-shrink: 0;
  color: var(--gray-500);
  transition: transform var(--duration) var(--ease);
}
.accordion-trigger[aria-expanded="true"] .chevron { transform: rotate(180deg); }

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 350ms var(--ease), padding 350ms var(--ease);
  background: var(--red-100);
}
.accordion-content.open { max-height: 300px; padding: var(--sp-4) var(--sp-6) var(--sp-6) calc(var(--sp-6) + 56px); }
.accordion-content p { color: var(--gray-700); line-height: 1.7; margin-bottom: var(--sp-3); }
.acc-link { font-size: 0.875rem; font-weight: 600; color: var(--red-500); }
.acc-link:hover { color: var(--red-600); text-decoration: underline; }

/* ============================================================
   GET INVOLVED
   ============================================================ */
.get-involved {
  padding: var(--sp-20) 0;
  background: var(--gray-100);
}

.involve-grid {
  display: grid;
  gap: var(--sp-6);
  grid-template-columns: 1fr;
}
@media (min-width: 768px) { .involve-grid { grid-template-columns: repeat(3, 1fr); } }

.involve-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  transition: transform var(--duration) var(--ease), box-shadow var(--duration) var(--ease);
}
.involve-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.involve-img {
  height: 200px;
  overflow: hidden;
}
.involve-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms var(--ease);
}
.involve-card:hover .involve-img img { transform: scale(1.04); }

.involve-body {
  padding: var(--sp-6);
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: var(--sp-4);
}
.involve-body h3 { color: var(--navy-700); }
.involve-body p { color: var(--gray-500); font-size: 0.9375rem; line-height: 1.65; flex: 1; }

/* ============================================================
   NEWS CAROUSEL
   ============================================================ */
.news {
  padding: var(--sp-20) 0;
  background: var(--white);
}

.news-header-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: var(--sp-8) !important;
  text-align: left;
}
.news-header-row > div { text-align: left; }

.carousel-controls { display: flex; gap: var(--sp-2); flex-shrink: 0; }
.carousel-btn {
  width: 40px; height: 40px;
  border-radius: var(--radius-full);
  border: 1.5px solid var(--gray-300);
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-700);
  transition: background var(--duration), color var(--duration), border-color var(--duration);
}
.carousel-btn:hover { background: var(--red-500); color: var(--white); border-color: var(--red-500); }
.carousel-btn:disabled { opacity: 0.35; pointer-events: none; }

.news-carousel-wrap { overflow: hidden; border-radius: var(--radius-lg); }
.news-carousel {
  display: flex;
  gap: var(--sp-6);
  transition: transform 350ms var(--ease);
  /* will set width dynamically via JS */
}

.news-card {
  flex-shrink: 0;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--duration);
}
.news-card:hover { box-shadow: var(--shadow-md); }

.news-img {
  height: 180px;
  overflow: hidden;
}
.news-img img { width: 100%; height: 100%; object-fit: cover; }

.news-card > .news-tag { margin: var(--sp-4) var(--sp-5) 0; }
.news-card h3 { padding: var(--sp-3) var(--sp-5) 0; color: var(--navy-700); font-size: 1rem; }
.news-card p { padding: var(--sp-2) var(--sp-5) 0; color: var(--gray-500); font-size: 0.875rem; line-height: 1.6; flex: 1; }
.news-link { display: inline-block; margin: var(--sp-4) var(--sp-5) var(--sp-5); font-size: 0.8125rem; font-weight: 600; color: var(--red-500); }
.news-link:hover { color: var(--red-600); text-decoration: underline; }

.news-tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-full);
}
.news-tag.urgent { background: oklch(95% 0.05 22); color: var(--red-600); }
.news-tag.campaign { background: oklch(94% 0.05 180); color: oklch(35% 0.12 180); }
.news-tag.story { background: oklch(94% 0.04 70); color: oklch(40% 0.12 70); }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: var(--sp-2);
  margin-top: var(--sp-8);
}
.dot {
  width: 8px; height: 8px;
  border-radius: var(--radius-full);
  background: var(--gray-300);
  transition: background var(--duration), width var(--duration);
  cursor: pointer;
  border: none;
}
.dot.active { background: var(--red-500); width: 20px; }

/* ============================================================
   DONATE CTA
   ============================================================ */
.donate-cta {
  background: var(--red-600);
  padding: var(--sp-20) 0;
  color: var(--white);
}

.donate-inner {
  display: grid;
  gap: var(--sp-12);
  grid-template-columns: 1fr;
  align-items: center;
}
@media (min-width: 768px) { .donate-inner { grid-template-columns: 1fr 1fr; } }

.donate-text h2 { color: var(--white); margin-bottom: var(--sp-4); }
.donate-text p { color: oklch(92% 0.04 22); line-height: 1.7; margin-bottom: var(--sp-8); }
.donate-text strong { color: var(--white); }

.amount-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-4);
}
.amount-item {
  background: oklch(100% 0 0 / 0.12);
  border: 1px solid oklch(100% 0 0 / 0.2);
  border-radius: var(--radius-lg);
  padding: var(--sp-5) var(--sp-4);
  transition: background var(--duration);
}
.amount-item:hover { background: oklch(100% 0 0 / 0.18); }
.amount-value { font-size: 1.5rem; font-weight: 800; color: var(--white); margin-bottom: var(--sp-2); }
.amount-desc { font-size: 0.8125rem; color: oklch(90% 0.04 22); line-height: 1.4; }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--navy-800);
  color: var(--gray-300);
  padding-top: var(--sp-16);
}

.footer-top {
  display: grid;
  gap: var(--sp-12);
  grid-template-columns: 1fr;
  margin-bottom: var(--sp-12);
}
@media (min-width: 768px) { .footer-top { grid-template-columns: 260px 1fr; } }

.logo-footer .logo-name { color: var(--white); }
.logo-footer .logo-tagline { color: oklch(60% 0.03 240); }
.footer-mission { font-size: 0.875rem; color: oklch(60% 0.03 240); line-height: 1.7; margin-top: var(--sp-4); max-width: 240px; }

.footer-social {
  display: flex;
  gap: var(--sp-3);
  margin-top: var(--sp-6);
