   Global Aid Alliance — Stylesheet
   OKLCH color palette, mobile-first, accessible
   ============================================================ */

/* --- DESIGN TOKENS --- */
:root {
  /* Brand Colors (OKLCH) */
  --red-700:   oklch(35% 0.18 22);   /* deep crimson — headers, active states */
  --red-600:   oklch(42% 0.20 22);   /* primary brand red */
  --red-500:   oklch(50% 0.22 22);   /* #C41E3A equivalent */
  --red-400:   oklch(60% 0.18 22);   /* hover red */
  --red-100:   oklch(95% 0.04 22);   /* light red tint */
  --navy-800:  oklch(22% 0.06 240);  /* deepest navy */
  --navy-700:  oklch(28% 0.08 240);  /* #1B3A5C equivalent */
  --navy-600:  oklch(35% 0.09 240);
  --navy-100:  oklch(95% 0.02 240);
  --gray-900:  oklch(15% 0.01 240);
  --gray-700:  oklch(35% 0.01 240);
  --gray-500:  oklch(55% 0.01 240);
  --gray-300:  oklch(78% 0.01 240);
  --gray-100:  oklch(96% 0.005 240);
  --white:     oklch(100% 0 0);
  --warm-50:   oklch(98% 0.005 70);

  /* Typography */
  --font-head: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing scale */
  --sp-1: 0.25rem;
  --sp-2: 0.5rem;
  --sp-3: 0.75rem;
  --sp-4: 1rem;
  --sp-6: 1.5rem;
  --sp-8: 2rem;
  --sp-10: 2.5rem;
  --sp-12: 3rem;
  --sp-16: 4rem;
  --sp-20: 5rem;
  --sp-24: 6rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.10), 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 6px oklch(0% 0 0 / 0.07), 0 2px 4px oklch(0% 0 0 / 0.06);
  --shadow-lg: 0 10px 15px oklch(0% 0 0 / 0.10), 0 4px 6px oklch(0% 0 0 / 0.05);
  --shadow-xl: 0 20px 25px oklch(0% 0 0 / 0.12), 0 8px 10px oklch(0% 0 0 / 0.06);

  /* Transitions */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 220ms;
}

/* --- RESET & BASE --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* --- CONTAINER --- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

/* --- BUTTONS --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-2);
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1;
  border-radius: var(--radius-md);
  padding: 0.75rem 1.5rem;
  transition: background var(--duration) var(--ease),
              color var(--duration) var(--ease),
              transform 120ms var(--ease),
              box-shadow var(--duration) var(--ease);
  white-space: nowrap;
}

.btn-donate {
  background: var(--red-500);
  color: var(--white);
  border-radius: var(--radius-full);
  padding: 0.55rem 1.25rem;
  font-size: 0.875rem;
}
.btn-donate:hover { background: var(--red-400); box-shadow: var(--shadow-md); }

.btn-hero-primary {
  background: var(--red-500);
  color: var(--white);
  padding: 0.875rem 2rem;
  font-size: 1rem;
  box-shadow: var(--shadow-md);
}
.btn-hero-primary:hover { background: var(--red-400); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn-hero-primary:active { transform: translateY(0); }

.btn-hero-secondary {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.75);
  padding: 0.875rem 2rem;
