.btn-outline:hover { background: var(--red-500); color: var(--white); }

/* --- SECTION LABELS & HEADERS --- */
.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
