  .main-nav .nav-donate { margin-left: 0; margin-top: var(--sp-4); text-align: center; }
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: 580px;
  display: flex;
  align-items: center;
  padding: var(--sp-20) 0;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    oklch(22% 0.06 240 / 0.92) 0%,
    oklch(22% 0.06 240 / 0.75) 50%,
    oklch(22% 0.06 240 / 0.30) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  background: var(--red-500);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
